// 卫语句模式（Guard Clause）
public void process(User user) {
    if (user == null) {
        throw new UserNotFound();
    }
    if (!user.isActive()) {
        throw new UserNotActive();
    }
    if (!user.hasPermission("read")) {
        throw new NoReadPermission();
    }
    if (!user.hasPermission("write")) {
        throw new NoWritePermission();
    }
    // 核心逻辑（无嵌套）
    doProcess(user);
}
// 提取条件为方法
if (canEditPost(user, post)) {
    editPost(post);
}
private boolean canEditPost(User user, Post post) {
    return user.isAuthor(post) || 
           user.hasRole(Role.EDITOR);
}
// 使用策略模式替代复杂条件
