// 循环内修改循环变量
for (int i = 0; i < items.size(); i++) {
    if (items.get(i).isSpecial()) {
        items.remove(i); // 跳过下一个元素
        i--; // 补救措施
    }
}
// 循环内包含循环控制逻辑
for (Item item : items) {
    if (item.isInvalid()) {
        break; // 在循环中判断退出
    }
    if (item.shouldSkip()) {
        continue; // 多处跳过逻辑
    }
    // 处理逻辑
    if (item.isLast()) {
        break; // 又一个退出点
    }
}
// 循环过长
for (Order order : orders) {
    // 200+ 行处理逻辑
}
```
#### ✅ 正面案例
```java
// 使用迭代器或新集合
Iterator<Item> iterator = items.iterator();
while (iterator.hasNext()) {
    if (iterator.next().isSpecial()) {
        iterator.remove(); // 安全删除
    }
}
// 或使用 Stream
items = items.stream()
    .filter(item -> !item.isSpecial())
    .collect(Collectors.toList());
// 提取循环体为函数
for (Order order : orders) {
    processOrder(order);
}
// 循环注释说明退出条件
// 处理订单直到遇到第一个无效订单或处理完所有订单
for (Order order : orders) {
    if (order.isInvalid()) {
        break;
    }
    processOrder(order);
}
// 使用枚举替代复杂循环
for (Direction direction : Direction.values()) {
    move(direction);
}
